const max_max_frame_size: usize = 16_777_215;
const default_max_header_list_size: usize = 16 * 1024;
// Zig 0.16 Threaded networking submits at most eight iovecs. DATA consumes a
// header/payload pair, so four frames make one actual syscall burst. HEADERS
// occupies the first pair and leaves room for three DATA frames.
const max_data_frames_per_write: usize = 4;
const max_data_frames_with_headers: usize = 3;
const graceful_shutdown_ping_payload = [8]u8{
    0x0b, 0x7b, 0xa2, 0xf0, 0x8b, 0x9b, 0xfe, 0x54,
};

const DataSliceCursor = struct {
    slices: []const []const u8,
    slice_index: usize = 0,
    slice_offset: usize = 0,

    fn appendTo(
        self: *DataSliceCursor,
        output: [][]const u8,
        output_len: *usize,
        len: usize,
    ) void {
        var remaining = len;
        while (remaining != 0) {
            while (self.slice_index < self.slices.len and
                self.slice_offset == self.slices[self.slice_index].len)
            {
                self.slice_index += 1;
                self.slice_offset = 0;
            }
            std.debug.assert(self.slice_index < self.slices.len);
            const slice = self.slices[self.slice_index];
            const count = @min(remaining, slice.len - self.slice_offset);
            std.debug.assert(output_len.* < output.len);
            output[output_len.*] =
                slice[self.slice_offset..][0..count];
            output_len.* += 1;
            self.slice_offset += count;
            remaining -= count;
        }
    }
};

fn readSome(
    io: std.Io,
    stream: net.Stream,
    buffer: []u8,
) net.Stream.Reader.Error!usize {
    var buffers = [_][]u8{buffer};
    return io.vtable.netRead(
        io.userdata,
        stream.socket.handle,
        &buffers,
    );
}

fn writeAllToStream(
    io: std.Io,
    stream: net.Stream,
    bytes: []const u8,
) net.Stream.Writer.Error!void {
    var written: usize = 0;
    while (written < bytes.len) {
        const n = try io.vtable.netWrite(
            io.userdata,
            stream.socket.handle,
            bytes[written..],
            &.{""},
            0,
        );
        if (n == 0) return error.SocketUnconnected;
        written += n;
    }
}

const RuntimeTransport = union(enum) {
    tcp: struct { io: std.Io, stream: net.Stream },
    tls_client: *tls_stream.ClientConnection,
    tls_server: *tls_stream.ServerConnection,

    pub fn read(self: RuntimeTransport, buffer: []u8) Error!usize {
        return switch (self) {
            .tcp => |tcp| readSome(tcp.io, tcp.stream, buffer),
            .tls_client => |connection| connection.read(buffer),
            .tls_server => |connection| connection.read(buffer),
        };
    }

    pub fn readWithDeadline(
        self: RuntimeTransport,
        buffer: []u8,
        deadline: std.Io.Clock.Timestamp,
    ) Error!usize {
        return switch (self) {
            .tcp => |tcp| stream_io.readSomeWithDeadline(
                tcp.io,
                tcp.stream,
                buffer,
                deadline,
            ),
            .tls_client => |connection| connection.readWithDeadline(buffer, deadline),
            .tls_server => |connection| connection.readWithDeadline(buffer, deadline),
        };
    }

    fn writeAll(self: RuntimeTransport, bytes: []const u8) Error!void {
        return switch (self) {
            .tcp => |tcp| writeAllToStream(tcp.io, tcp.stream, bytes),
            .tls_client => |connection| connection.writeAll(bytes),
            .tls_server => |connection| connection.writeAll(bytes),
        };
    }

    pub fn writeAllWithDeadline(
        self: RuntimeTransport,
        bytes: []const u8,
        committed: *usize,
        deadline: std.Io.Clock.Timestamp,
    ) Error!void {
        return switch (self) {
            .tcp => |tcp| stream_io.writeAllTrackedWithDeadline(
                tcp.io,
                tcp.stream,
                bytes,
                committed,
                deadline,
            ),
            .tls_client => |connection| connection.writeAllWithDeadline(
                bytes,
                committed,
                deadline,
            ),
            .tls_server => |connection| connection.writeAllWithDeadline(
                bytes,
                committed,
                deadline,
            ),
        };
    }

    pub fn writeAllParts(
        self: RuntimeTransport,
        header: []const u8,
        payload: []const u8,
    ) Error!void {
        return switch (self) {
            .tcp => |tcp| stream_io.writeAllParts(
                tcp.io,
                tcp.stream,
                header,
                payload,
            ),
            .tls_client => |connection| connection.writeAllParts(
                header,
                payload,
            ),
            .tls_server => |connection| connection.writeAllParts(
                header,
                payload,
            ),
        };
    }

    fn writeAllSlices(
        self: RuntimeTransport,
        parts: []const []const u8,
    ) Error!void {
        return switch (self) {
            .tcp => |tcp| stream_io.writeAllSlicesWide(
                tcp.io,
                tcp.stream,
                parts,
            ),
            .tls_client => |connection| connection.writeAllSlices(parts),
            .tls_server => |connection| connection.writeAllSlices(parts),
        };
    }

    fn close(self: RuntimeTransport) void {
        switch (self) {
            .tcp => |tcp| tcp.stream.close(tcp.io),
            .tls_client => |connection| connection.deinit(),
            .tls_server => |connection| connection.deinit(),
        }
    }

    fn updateTrafficKeys(
        self: RuntimeTransport,
        request_peer_update: bool,
    ) Error!void {
        return switch (self) {
            .tls_client => |connection| connection.updateTrafficKeys(
                request_peer_update,
            ),
            .tls_server => |connection| connection.updateTrafficKeys(
                request_peer_update,
            ),
            .tcp => error.PostHandshakeTlsUnavailable,
        };
    }

    fn keyUpdateCounts(
        self: *const RuntimeTransport,
    ) ?tls_stream.KeyUpdateCounts {
        return switch (self.*) {
            .tls_client => |connection| connection.keyUpdateCounts(),
            .tls_server => |connection| connection.keyUpdateCounts(),
            .tcp => null,
        };
    }
};

fn tcpTransport(io: std.Io, stream: net.Stream) RuntimeTransport {
    return .{ .tcp = .{ .io = io, .stream = stream } };
}

fn connectionHandshakeDeadline(
    transport: RuntimeTransport,
    timeout: ?std.Io.Duration,
) Error!?std.Io.Clock.Timestamp {
    const duration = timeout orelse return null;
    if (duration.nanoseconds <= 0) return error.Timeout;
    const io = switch (transport) {
        .tcp => |tcp| tcp.io,
        .tls_client => |connection| connection.io,
        .tls_server => |connection| connection.io,
    };
    return .fromNow(io, .{ .raw = duration, .clock = .awake });
}

fn connectionHandshakeDeadlineBefore(
    transport: RuntimeTransport,
    deadline: std.Io.Clock.Timestamp,
    timeout: ?std.Io.Duration,
) Error!std.Io.Clock.Timestamp {
    const io = switch (transport) {
        .tcp => |tcp| tcp.io,
        .tls_client => |connection| connection.io,
        .tls_server => |connection| connection.io,
    };
    return deadline_policy.capTimeout(io, deadline, timeout);
}

pub const Limits = struct {
    /// Local allocation/test ceiling for any inbound or outbound frame payload.
    /// `max_frame_size` below is the HTTP/2 SETTINGS_MAX_FRAME_SIZE value that
    /// can be advertised to peers and must stay within RFC 9113 bounds.
    max_frame_payload: usize = 16 * 1024 * 1024,
    max_body_bytes: usize = 16 * 1024 * 1024,
    max_header_fields: usize = 256,
    /// Maximum interim response heads accepted before a final response. This
    /// bounds both HPACK work and observer callbacks from an endless 1xx chain.
    max_informational_responses: usize = 16,
    /// Bounds HEADERS/PUSH_PROMISE continuation chains independently from byte
    /// limits.  Rust h2 derives this from SETTINGS_MAX_HEADER_LIST_SIZE and the
    /// receive frame size to prevent peers from sending endless empty
    /// CONTINUATION frames that never grow the header block.
    max_continuation_frames: ?usize = null,
    /// Local HPACK decoder capacity advertised as SETTINGS_HEADER_TABLE_SIZE.
    /// Values above u32 are rejected because the wire setting is 32-bit.
    header_table_size: usize = http2.Hpack.default_dynamic_table_size,
    initial_window_size: u32 = @intCast(default_flow_window),
    /// Desired receive-side connection window. HTTP/2 starts every connection
    /// at 65,535 bytes, so values above that are established with an initial
    /// connection WINDOW_UPDATE after SETTINGS. This is distinct from
    /// SETTINGS_INITIAL_WINDOW_SIZE, which applies per stream.
    initial_connection_window_size: u32 =
        @intCast(default_flow_window),
    /// Adapt receive windows from measured DATA throughput and a dedicated
    /// PING RTT sample. Disabled by default so configured fixed-window wire
    /// behavior remains unchanged.
    adaptive_window: bool = false,
    adaptive_window_max: u32 = bdp.default_max_window,
    max_concurrent_streams: ?u32 = null,
    max_frame_size: usize = default_max_frame_size,
    /// Local decoded header-list limit advertised as
    /// SETTINGS_MAX_HEADER_LIST_SIZE. Values above u32 are rejected because
    /// they cannot be represented without changing the advertised policy.
    max_header_list_size: usize = default_max_header_list_size,
    /// Local cap for PRIORITY_UPDATE records that target request streams not
    /// opened yet. This remains effective even when MAX_CONCURRENT_STREAMS is
    /// not advertised, preventing unbounded state from speculative IDs.
    max_idle_priority_updates: usize = 256,
    /// Maximum distinct RFC 8336 origins retained from the peer for the
    /// lifetime of one connection. Additional advisory entries are ignored.
    max_peer_origins: usize = 256,
    /// Maximum distinct RFC 7838 (stream ID, origin) advertisements retained
    /// from the peer. Existing entries may still be replaced at capacity.
    max_alternative_services: usize = 256,
    /// Maximum application frames retained while an explicit PING round trip
    /// waits for its matching ACK. Each retained frame is independently
    /// bounded by the inbound frame-size limits. Reaching this cap fails the
    /// probe without discarding any frame already removed from the transport.
    max_pending_ping_frames: usize = 256,
    /// Maximum recently locally-reset stream IDs retained so late DATA,
    /// HEADERS, and duplicate RST_STREAM frames can be discarded without
    /// terminating the connection. Zero disables this tolerance.
    max_reset_stream_history: usize = 64,
    /// Minimum time that a tracked locally-reset stream remains eligible for
    /// late-frame tolerance. Expired entries are reclaimed lazily when the
    /// history needs capacity or a retained ID is queried.
    reset_stream_duration: std.Io.Duration = .fromSeconds(1),
    /// Maximum remotely-reset requests allowed to remain in the pending-accept
    /// queue. Those requests no longer count toward stream concurrency, so a
    /// peer can otherwise churn reset-after-HEADERS requests and retain owned
    /// request allocations until the application reaches them.
    max_pending_accept_reset_streams: usize = 20,
    /// Maximum RST_STREAM frames generated because the peer caused a
    /// stream-local protocol error over the lifetime of one connection. The
    /// count never decreases: reaching the limit turns the next such reset
    /// into GOAWAY(ENHANCE_YOUR_CALM). `null` disables this DoS guard.
    max_local_error_reset_streams: ?usize = 1024,
    /// Absolute budget for DNS resolution plus all TCP connection attempts.
    /// TLS and HTTP/2 handshake timeouts remain independent.
    connect_timeout: ?std.Io.Duration = null,
    /// Optional absolute budget for the HTTP/2 connection preface and initial
    /// SETTINGS exchange after TCP/TLS setup. Interleaved permitted control
    /// frames do not renew this deadline. For h2c Upgrade, the same duration
    /// first bounds the HTTP/1 request/response head and a fresh budget starts
    /// after the 101 response for the HTTP/2 bootstrap exchange.
    handshake_timeout: ?std.Io.Duration = null,
    /// Advertise RFC 8441 SETTINGS_ENABLE_CONNECT_PROTOCOL.  It is disabled by
    /// default because peers may start tunnelling arbitrary bytes on streams
    /// once extended CONNECT is accepted.
    enable_connect_protocol: bool = false,
    /// Explicitly opt in to HTTP/2 server push. The client otherwise sends
    /// SETTINGS_ENABLE_PUSH=0 and rejects PUSH_PROMISE.
    enable_push: bool = false,
    /// Add an IMF-fixdate `date` field to final server responses that do not
    /// already provide one. This matches Hyper's default server behavior.
    auto_date_header: bool = true,
    /// Advertise RFC 9218 SETTINGS_NO_RFC7540_PRIORITIES=1. This allows a
    /// client to use PRIORITY_UPDATE and tells the peer that legacy dependency
    /// signals are intentionally ignored.
    no_rfc7540_priorities: bool = false,
    /// Disable Nagle on HTTP/2 TCP connections. HTTP/2 already provides its
    /// own frame and stream aggregation; retaining Nagle can stall a complete
    /// flow-control burst behind Linux's delayed ACK timer.
    tcp_nodelay: bool = true,
};

/// Scheduling policy for one blocking HTTP/2 keep-alive cycle.
///
/// Unlike an async background driver, `Connection.keepAlive` temporarily owns
/// inbound frame pumping. Call it only when no other reader is active.
pub const KeepAliveOptions = struct {
    /// Send the probe after this much peer receive inactivity.
    interval: std.Io.Duration,
    /// Fail when the matching ACK does not arrive within this budget.
    timeout: std.Io.Duration = .fromSeconds(20),
    /// Permit a probe when no locally or remotely initiated streams are live.
    /// Hyper clients default this to false; Hyper servers effectively use true.
    while_idle: bool = false,
};

pub const KeepAliveResult = enum {
    skipped_idle,
    acknowledged,
};

pub const KeepAlive = struct {
    options: KeepAliveOptions,
    next_payload: u64 = 0,

    pub fn init(options: KeepAliveOptions) Error!KeepAlive {
        if (options.interval.nanoseconds <= 0 or
            options.timeout.nanoseconds <= 0)
        {
            return error.Timeout;
        }
        return .{ .options = options };
    }

    /// Run one cycle and advance the opaque payload only after its ACK. This
    /// gives long-lived drivers deterministic, non-repeating probes without
    /// requiring an allocator or random source.
    pub fn run(self: *KeepAlive, connection: *Connection) Error!KeepAliveResult {
        var payload: [8]u8 = undefined;
        std.mem.writeInt(u64, &payload, self.next_payload, .big);
        const result = try connection.keepAlive(payload, self.options);
        if (result == .acknowledged) self.next_payload +%= 1;
        return result;
    }
};

pub const Server = struct {
    io: std.Io,
    listener: net.Server,
    allocator: std.mem.Allocator,
    limits: Limits = .{},

    pub fn listen(allocator: std.mem.Allocator, io: std.Io, bind_address: net.IpAddress, limits: Limits) Error!Server {
        try validateLocalLimits(limits);
        return .{
            .io = io,
            .allocator = allocator,
            .listener = try bind_address.listen(io, .{ .reuse_address = true }),
            .limits = limits,
        };
    }

    pub fn deinit(self: *Server) void {
        self.listener.deinit(self.io);
        self.* = undefined;
    }

    pub fn address(self: Server) net.IpAddress {
        return self.listener.socket.address;
    }

    pub fn accept(self: *Server) Error!Connection {
        const stream = try self.listener.accept(self.io);
        return self.acceptStream(stream);
    }

    /// Apply one caller-owned deadline to TCP accept and HTTP/2 bootstrap.
    pub fn acceptWithDeadline(
        self: *Server,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        _ = try deadline_policy.usableAwake(self.io, deadline);
        const stream = try accept_deadline.withDeadline(
            &self.listener,
            self.io,
            deadline,
        );
        return self.acceptStreamWithDeadline(stream, deadline);
    }

    pub fn acceptWithTimeout(
        self: *Server,
        timeout: std.Io.Duration,
    ) Error!Connection {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        const deadline = std.Io.Clock.Timestamp.fromNow(
            self.io,
            .{ .raw = timeout, .clock = .awake },
        );
        const stream = try accept_deadline.withDeadline(
            &self.listener,
            self.io,
            deadline,
        );
        return self.acceptStreamWithDeadline(stream, deadline);
    }

    /// Complete the HTTP/2 server handshake on an already-accepted stream.
    ///
    /// Separating transport acceptance from the handshake lets event loops
    /// dispatch each socket independently: a peer that opens TCP but delays
    /// its connection preface must not prevent the listener from accepting
    /// other peers. Ownership of `stream` transfers to this function.
    pub fn acceptStream(
        self: *Server,
        stream: net.Stream,
    ) Error!Connection {
        return self.acceptStreamMaybeBefore(stream, null);
    }

    pub fn acceptStreamWithDeadline(
        self: *Server,
        stream: net.Stream,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        _ = try deadline_policy.usableAwake(self.io, deadline);
        return self.acceptStreamMaybeBefore(stream, deadline);
    }

    pub fn acceptStreamWithTimeout(
        self: *Server,
        stream: net.Stream,
        timeout: std.Io.Duration,
    ) Error!Connection {
        // Validation precedes ownership transfer, matching the absolute form.
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.acceptStreamWithDeadline(
            stream,
            .fromNow(self.io, .{ .raw = timeout, .clock = .awake }),
        );
    }

    fn acceptStreamMaybeBefore(
        self: *Server,
        stream: net.Stream,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!Connection {
        var stream_owned = true;
        errdefer if (stream_owned) stream.close(self.io);
        if (self.limits.tcp_nodelay) {
            try socket_options.setTcpNoDelay(stream);
        }
        // The transport handshake owns cleanup from this point, including
        // failures before it can return a Connection.
        stream_owned = false;
        return acceptConnectionTransportMaybeBefore(
            self.allocator,
            self.io,
            stream,
            tcpTransport(self.io, stream),
            self.limits,
            deadline,
        );
    }

    pub fn acceptUpgrade(self: *Server) Error!H2cUpgradeRequest {
        return self.acceptUpgradeMaybeBefore(null);
    }

    /// Accept an h2c Upgrade under one caller-owned awake-clock deadline. The
    /// budget spans TCP accept, the complete HTTP/1.1 request,
    /// the 101 write, client preface/SETTINGS, and SETTINGS acknowledgement.
    pub fn acceptUpgradeWithDeadline(
        self: *Server,
        deadline: std.Io.Clock.Timestamp,
    ) Error!H2cUpgradeRequest {
        _ = try deadline_policy.usableAwake(self.io, deadline);
        return self.acceptUpgradeMaybeBefore(deadline);
    }

    pub fn acceptUpgradeWithTimeout(
        self: *Server,
        timeout: std.Io.Duration,
    ) Error!H2cUpgradeRequest {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.acceptUpgradeWithDeadline(.fromNow(
            self.io,
            .{ .raw = timeout, .clock = .awake },
        ));
    }

    fn acceptUpgradeMaybeBefore(
        self: *Server,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!H2cUpgradeRequest {
        const stream = if (deadline) |absolute|
            try accept_deadline.withDeadline(&self.listener, self.io, absolute)
        else
            try self.listener.accept(self.io);
        var stream_owned = true;
        errdefer if (stream_owned) stream.close(self.io);
        if (self.limits.tcp_nodelay) {
            try socket_options.setTcpNoDelay(stream);
        }

        var request = if (deadline) |absolute|
            try http1_runtime.readRequestFromStreamWithDeadline(
                self.allocator,
                self.io,
                stream,
                limitsToHttp1(self.limits),
                .{},
                absolute,
            )
        else
            try http1_runtime.readRequestFromStream(
                self.allocator,
                self.io,
                stream,
                limitsToHttp1(self.limits),
                .{},
            );
        errdefer request.deinit(self.allocator);
        try validateH2cUpgradeRequest(request.request);

        const settings_header = (try optionalHttp1SingletonHeader(request.request.headers, "http2-settings")) orelse return error.InvalidHeader;
        const advertised_settings = try decodeHttp2SettingsHeader(self.allocator, settings_header);
        defer self.allocator.free(advertised_settings);

        try http1_runtime.writeResponseToStream(self.allocator, self.io, stream, .{
            .status = 101,
            .reason = "Switching Protocols",
            .headers = &.{
                .{ .name = "Connection", .value = "Upgrade" },
                .{ .name = "Upgrade", .value = "h2c" },
            },
            .request_method = request.request.method,
        });

        const transport = tcpTransport(self.io, stream);
        // Parsing the HTTP/1 request has its own bounded head phase. Once the
        // protocol switch is committed, one new deadline spans every byte of
        // the client preface, its repeated SETTINGS, and its server-SETTINGS
        // acknowledgement. Partial frames cannot turn this into an idle timer.
        const handshake_deadline = if (deadline) |absolute|
            try connectionHandshakeDeadlineBefore(
                transport,
                absolute,
                self.limits.handshake_timeout,
            )
        else
            try connectionHandshakeDeadline(
                transport,
                self.limits.handshake_timeout,
            );
        var preface_buf: [http2.connection_preface.len]u8 = undefined;
        try readExactTransportWithDeadline(
            transport,
            &preface_buf,
            handshake_deadline,
        );
        try http2.validateClientPreface(&preface_buf);

        var client_settings = try readHandshakeFrameTransportWithDeadline(
            self.allocator,
            transport,
            self.limits,
            handshake_deadline,
        );
        defer client_settings.deinit(self.allocator);
        if (client_settings.frame.header.frame_type != .settings or (client_settings.frame.header.flags & flag_ack) != 0) {
            return error.UnexpectedFrame;
        }
        if (!std.mem.eql(u8, advertised_settings, client_settings.frame.payload)) return error.InvalidFrame;
        const peer_settings = try parsePeerSettingsTransport(
            self.allocator,
            transport,
            client_settings.frame.payload,
            handshake_deadline,
        );
        defer self.allocator.free(peer_settings);

        try writeInitialSettingsTransport(
            self.allocator,
            transport,
            self.limits,
            .server,
        );
        try writeInitialConnectionWindowTransport(
            self.allocator,
            transport,
            self.limits,
        );
        try writeFrameTransport(
            self.allocator,
            transport,
            .settings,
            flag_ack,
            0,
            &.{},
        );

        // The HTTP/1 Upgrade request already occupies stream 1, so the next
        // frame the server sees after its SETTINGS is normally the client's
        // SETTINGS ACK rather than HEADERS for stream 1.  Consume it here so
        // applications can immediately answer the upgraded request without
        // leaving unread control bytes that would make a short-lived test/server
        // close look like a TCP reset to the client.
        var client_ack = try readHandshakeFrameTransportWithDeadline(
            self.allocator,
            transport,
            self.limits,
            handshake_deadline,
        );
        defer client_ack.deinit(self.allocator);
        if (client_ack.frame.header.frame_type != .settings or (client_ack.frame.header.flags & flag_ack) == 0) {
            return error.UnexpectedFrame;
        }

        var connection = Connection{
            .io = self.io,
            .allocator = self.allocator,
            .stream = stream,
            .transport = transport,
            .role = .server,
            .limits = self.limits,
            .last_peer_frame_at = std.Io.Clock.awake.now(self.io),
            .awaiting_settings_ack = false,
            .last_peer_client_stream_id = 1,
            .last_peer_processed_stream_id = 1,
        };
        connection.applyLocalLimits();
        errdefer connection.close();
        try connection.applySettings(peer_settings);
        try connection.reservePeerStream(1);
        errdefer connection.releasePeerStream(1);
        try connection.rememberResponseSemantics(
            1,
            request.request.method.string(),
            null,
            .{},
        );

        stream_owned = false;
        return .{ .connection = connection, .request = request, .stream_id = 1 };
    }

    pub fn serveConnection(
        self: *Server,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (*HandlerContext, OwnedRequest) Error!ResponseOptions,
        max_requests: usize,
    ) Error!usize {
        var connection = try self.accept();
        defer connection.close();
        return connection.serve(HandlerContext, context, handler, max_requests);
    }

    pub fn serveConcurrent(
        self: *Server,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (*HandlerContext, OwnedRequest) Error!ResponseOptions,
        max_connections: usize,
    ) AsyncServeError!ConcurrentServeResult {
        return serveAcceptedConcurrent(
            Server,
            self,
            self.io,
            self.allocator,
            HandlerContext,
            context,
            handler,
            max_connections,
        );
    }

    pub fn serveUntil(
        self: *Server,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (
            *HandlerContext,
            OwnedRequest,
        ) Error!ResponseOptions,
        max_connections: usize,
        max_requests_per_connection: usize,
        options: ServeUntilOptions,
    ) anyerror!void {
        return serveAcceptedUntil(
            Server,
            self,
            self.io,
            HandlerContext,
            context,
            handler,
            max_connections,
            max_requests_per_connection,
            options,
        );
    }
};

/// HTTP/2 prior-knowledge listener over a Unix-domain stream socket.
///
/// This shares the complete HTTP/2 connection state machine with TCP. The
/// filesystem socket path remains caller-owned and is not removed by deinit.
pub const UnixServer = struct {
    io: std.Io,
    listener: net.Server,
    allocator: std.mem.Allocator,
    limits: Limits = .{},

    pub fn listen(
        allocator: std.mem.Allocator,
        io: std.Io,
        address: net.UnixAddress,
        limits: Limits,
    ) Error!UnixServer {
        try validateLocalLimits(limits);
        return .{
            .io = io,
            .allocator = allocator,
            .listener = try address.listen(io, .{}),
            .limits = limits,
        };
    }

    pub fn deinit(self: *UnixServer) void {
        self.listener.deinit(self.io);
        self.* = undefined;
    }

    pub fn accept(self: *UnixServer) Error!Connection {
        const stream = try self.listener.accept(self.io);
        return acceptConnectionTransport(
            self.allocator,
            self.io,
            stream,
            tcpTransport(self.io, stream),
            self.limits,
        );
    }

    /// Apply one deadline to Unix accept and the HTTP/2 bootstrap.
    pub fn acceptWithDeadline(
        self: *UnixServer,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        _ = try deadline_policy.usableAwake(self.io, deadline);
        const stream = try accept_deadline.withDeadline(
            &self.listener,
            self.io,
            deadline,
        );
        return acceptConnectionTransportMaybeBefore(
            self.allocator,
            self.io,
            stream,
            tcpTransport(self.io, stream),
            self.limits,
            deadline,
        );
    }

    pub fn acceptWithTimeout(
        self: *UnixServer,
        timeout: std.Io.Duration,
    ) Error!Connection {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        const deadline = std.Io.Clock.Timestamp.fromNow(
            self.io,
            .{ .raw = timeout, .clock = .awake },
        );
        const stream = try accept_deadline.withDeadline(
            &self.listener,
            self.io,
            deadline,
        );
        return acceptConnectionTransportMaybeBefore(
            self.allocator,
            self.io,
            stream,
            tcpTransport(self.io, stream),
            self.limits,
            deadline,
        );
    }

    pub fn serveConnection(
        self: *UnixServer,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (
            *HandlerContext,
            OwnedRequest,
        ) Error!ResponseOptions,
        max_requests: usize,
    ) Error!usize {
        var connection = try self.accept();
        defer connection.close();
        return connection.serve(
            HandlerContext,
            context,
            handler,
            max_requests,
        );
    }

    pub fn serveConcurrent(
        self: *UnixServer,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (
            *HandlerContext,
            OwnedRequest,
        ) Error!ResponseOptions,
        max_connections: usize,
    ) AsyncServeError!ConcurrentServeResult {
        return serveAcceptedConcurrent(
            UnixServer,
            self,
            self.io,
            self.allocator,
            HandlerContext,
            context,
            handler,
            max_connections,
        );
    }

    pub fn serveUntil(
        self: *UnixServer,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (
            *HandlerContext,
            OwnedRequest,
        ) Error!ResponseOptions,
        max_connections: usize,
        max_requests_per_connection: usize,
        options: ServeUntilOptions,
    ) anyerror!void {
        return serveAcceptedUntil(
            UnixServer,
            self,
            self.io,
            HandlerContext,
            context,
            handler,
            max_connections,
            max_requests_per_connection,
            options,
        );
    }
};

fn acceptConnectionTransport(
    allocator: std.mem.Allocator,
    io: std.Io,
    stream: net.Stream,
    transport: RuntimeTransport,
    limits: Limits,
) Error!Connection {
    return acceptConnectionTransportMaybeBefore(
        allocator,
        io,
        stream,
        transport,
        limits,
        null,
    );
}

fn acceptConnectionTransportMaybeBefore(
    allocator: std.mem.Allocator,
    io: std.Io,
    stream: net.Stream,
    transport: RuntimeTransport,
    limits: Limits,
    outer_deadline: ?std.Io.Clock.Timestamp,
) Error!Connection {
    // Ownership enters with the transport so failures before Connection is
    // constructed (notably a preface timeout) still close TCP or TLS state.
    var transport_owned = true;
    errdefer if (transport_owned) transport.close();
    const deadline = if (outer_deadline) |absolute|
        try connectionHandshakeDeadlineBefore(
            transport,
            absolute,
            limits.handshake_timeout,
        )
    else
        try connectionHandshakeDeadline(
            transport,
            limits.handshake_timeout,
        );
    var preface_buf: [http2.connection_preface.len]u8 = undefined;
    try readExactTransportWithDeadline(
        transport,
        &preface_buf,
        deadline,
    );
    http2.validateClientPreface(&preface_buf) catch |err| {
        writeConnectionErrorGoAwayTransport(
            allocator,
            transport,
            .protocol_error,
            "invalid-preface",
        ) catch {};
        return err;
    };

    var client_settings = try readHandshakeFrameTransportWithDeadline(
        allocator,
        transport,
        limits,
        deadline,
    );
    defer client_settings.deinit(allocator);
    if (client_settings.frame.header.frame_type != .settings or
        (client_settings.frame.header.flags & flag_ack) != 0)
    {
        return error.UnexpectedFrame;
    }
    const peer_settings = try parsePeerSettingsTransport(
        allocator,
        transport,
        client_settings.frame.payload,
        deadline,
    );
    defer allocator.free(peer_settings);

    try writeInitialSettingsTransport(allocator, transport, limits, .server);
    try writeInitialConnectionWindowTransport(allocator, transport, limits);
    try writeFrameTransport(
        allocator,
        transport,
        .settings,
        flag_ack,
        0,
        &.{},
    );

    var connection = Connection{
        .io = io,
        .allocator = allocator,
        .stream = stream,
        .transport = transport,
        .role = .server,
        .limits = limits,
        .last_peer_frame_at = std.Io.Clock.awake.now(io),
        .awaiting_settings_ack = true,
    };
    transport_owned = false;
    errdefer connection.close();
    connection.applyLocalLimits();
    try connection.applySettings(peer_settings);
    return connection;
}

pub const TlsListenOptions = struct {
    identity: vail.tls.auth.ServerIdentity,
    limits: Limits = .{},
    cipher_suites: []const vail.tls.cipher_suite.Suite =
        &vail.tls.cipher_suite.default_preference,
    tls12_cipher_suites: []const tls_stream.Tls12CipherSuite =
        tls_stream.default_tls12_cipher_suites,
    protocol_policy: tls_stream.VersionPolicy = .tls12_and_tls13,
    tls13_session_tickets: ?tls_stream.Tls13ServerTicketPolicy = null,
    tls12_session_tickets: ?tls_stream.Tls12ServerTicketPolicy = null,
    max_client_hello_size: usize = 64 * 1024,
    max_client_handshake_size: usize = 256 * 1024,
    /// Absolute TLS handshake receive budget. HTTP/2 frame waits begin only
    /// after this transport handshake succeeds.
    tls_handshake_timeout: ?std.Io.Duration = null,
    client_auth: ?vail.tls.client_auth.ServerPolicy = null,
    tcp_nodelay: bool = true,
};

/// Native TLS 1.2/1.3 HTTP/2 listener. ALPN is mandatory and restricted to `h2`,
/// so HTTP/1 traffic can never enter the prior-knowledge HTTP/2 parser.
pub const TlsServer = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    listener: net.Server,
    limits: Limits,
    tls: tls_stream.ServerOptions,
    tcp_nodelay: bool,

    pub fn listen(
        allocator: std.mem.Allocator,
        io: std.Io,
        bind_address: net.IpAddress,
        options: TlsListenOptions,
    ) Error!TlsServer {
        try validateLocalLimits(options.limits);
        try options.identity.validate();
        return .{
            .allocator = allocator,
            .io = io,
            .listener = try bind_address.listen(
                io,
                .{ .reuse_address = true },
            ),
            .limits = options.limits,
            .tls = .{
                .identity = options.identity,
                .cipher_suites = options.cipher_suites,
                .tls12_cipher_suites = options.tls12_cipher_suites,
                .protocol_policy = options.protocol_policy,
                .tls13_session_tickets = options.tls13_session_tickets,
                .tls12_session_tickets = options.tls12_session_tickets,
                .max_client_hello_size = options.max_client_hello_size,
                .max_client_handshake_size = options.max_client_handshake_size,
                .handshake_timeout = options.tls_handshake_timeout,
                .client_auth = options.client_auth,
                .alpn_protocols = &.{"h2"},
            },
            .tcp_nodelay = options.tcp_nodelay,
        };
    }

    pub fn deinit(self: *TlsServer) void {
        self.listener.deinit(self.io);
        self.* = undefined;
    }

    pub fn address(self: TlsServer) net.IpAddress {
        return self.listener.socket.address;
    }

    pub fn accept(self: *TlsServer) Error!Connection {
        const stream = try self.listener.accept(self.io);
        return self.acceptStream(stream);
    }

    /// Carry one caller-owned deadline through TCP accept, TLS, and HTTP/2
    /// bootstrap.
    pub fn acceptWithDeadline(
        self: *TlsServer,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        _ = try deadline_policy.usableAwake(self.io, deadline);
        const stream = try accept_deadline.withDeadline(
            &self.listener,
            self.io,
            deadline,
        );
        return self.acceptStreamWithDeadline(stream, deadline);
    }

    pub fn acceptWithTimeout(
        self: *TlsServer,
        timeout: std.Io.Duration,
    ) Error!Connection {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        const deadline = std.Io.Clock.Timestamp.fromNow(
            self.io,
            .{ .raw = timeout, .clock = .awake },
        );
        const stream = try accept_deadline.withDeadline(
            &self.listener,
            self.io,
            deadline,
        );
        return self.acceptStreamWithDeadline(stream, deadline);
    }

    /// Complete TLS and HTTP/2 handshakes on an already accepted socket.
    /// Ownership transfers to the returned connection on success.
    pub fn acceptStream(
        self: *TlsServer,
        stream: net.Stream,
    ) Error!Connection {
        return self.acceptStreamMaybeBefore(stream, null);
    }

    pub fn acceptStreamWithDeadline(
        self: *TlsServer,
        stream: net.Stream,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        _ = try deadline_policy.usableAwake(self.io, deadline);
        return self.acceptStreamMaybeBefore(stream, deadline);
    }

    pub fn acceptStreamWithTimeout(
        self: *TlsServer,
        stream: net.Stream,
        timeout: std.Io.Duration,
    ) Error!Connection {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return self.acceptStreamWithDeadline(
            stream,
            .fromNow(self.io, .{ .raw = timeout, .clock = .awake }),
        );
    }

    fn acceptStreamMaybeBefore(
        self: *TlsServer,
        stream: net.Stream,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!Connection {
        var stream_owned = true;
        errdefer if (stream_owned) stream.close(self.io);
        if (self.tcp_nodelay) try socket_options.setTcpNoDelay(stream);
        const tls_connection = if (deadline) |absolute|
            try tls_stream.ServerConnection.initWithDeadline(
                self.allocator,
                self.io,
                stream,
                self.tls,
                absolute,
            )
        else
            try tls_stream.ServerConnection.init(
                self.allocator,
                self.io,
                stream,
                self.tls,
            );
        stream_owned = false;
        var tls_owned = true;
        errdefer if (tls_owned) tls_connection.deinit();
        if (tls_connection.selected_alpn == null or
            !std.mem.eql(u8, tls_connection.selected_alpn.?, "h2"))
        {
            return error.InvalidAlpn;
        }
        // acceptConnectionTransport owns transport cleanup from this point,
        // including failures before the HTTP/2 Connection exists.
        tls_owned = false;
        return acceptConnectionTransportMaybeBefore(
            self.allocator,
            self.io,
            stream,
            .{ .tls_server = tls_connection },
            self.limits,
            deadline,
        );
    }

    pub fn serveConnection(
        self: *TlsServer,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (
            *HandlerContext,
            OwnedRequest,
        ) Error!ResponseOptions,
        max_requests: usize,
    ) Error!usize {
        var connection = try self.accept();
        defer connection.close();
        return connection.serve(
            HandlerContext,
            context,
            handler,
            max_requests,
        );
    }

    pub fn serveConcurrent(
        self: *TlsServer,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (
            *HandlerContext,
            OwnedRequest,
        ) Error!ResponseOptions,
        max_connections: usize,
    ) AsyncServeError!ConcurrentServeResult {
        return serveAcceptedConcurrent(
            TlsServer,
            self,
            self.io,
            self.allocator,
            HandlerContext,
            context,
            handler,
            max_connections,
        );
    }

    pub fn serveUntil(
        self: *TlsServer,
        comptime HandlerContext: type,
        context: *HandlerContext,
        comptime handler: *const fn (
            *HandlerContext,
            OwnedRequest,
        ) Error!ResponseOptions,
        max_connections: usize,
        max_requests_per_connection: usize,
        options: ServeUntilOptions,
    ) anyerror!void {
        return serveAcceptedUntil(
            TlsServer,
            self,
            self.io,
            HandlerContext,
            context,
            handler,
            max_connections,
            max_requests_per_connection,
            options,
        );
    }
};

pub const AsyncServeError = Error || std.Io.Cancelable;

pub const ConcurrentServeResult = struct {
    allocator: std.mem.Allocator,
    errors: []?anyerror,

    pub fn deinit(self: *ConcurrentServeResult) void {
        self.allocator.free(self.errors);
        self.* = undefined;
    }

    pub fn firstError(self: ConcurrentServeResult) ?anyerror {
        for (self.errors) |err| {
            if (err) |value| return value;
        }
        return null;
    }

    pub fn successCount(self: ConcurrentServeResult) usize {
        var count: usize = 0;
        for (self.errors) |err| {
            if (err == null) count += 1;
        }
        return count;
    }
};

/// Per-request outcomes from one bounded same-connection concurrent handler
/// batch. A null slot means the response was written successfully. A handler
/// error is recorded after resetting that stream with INTERNAL_ERROR; an
/// accidental final 1xx is recorded as InvalidStatus after writing final 500.
pub const ConcurrentHandlerServeResult = struct {
    allocator: std.mem.Allocator,
    errors: []?anyerror,

    pub fn deinit(self: *ConcurrentHandlerServeResult) void {
        self.allocator.free(self.errors);
        self.* = undefined;
    }

    pub fn firstError(self: ConcurrentHandlerServeResult) ?anyerror {
        for (self.errors) |err| {
            if (err) |value| return value;
        }
        return null;
    }

    pub fn successCount(self: ConcurrentHandlerServeResult) usize {
        var count: usize = 0;
        for (self.errors) |err| {
            if (err == null) count += 1;
        }
        return count;
    }
};

pub const ConcurrentHandlerServeError = Error || std.Io.ConcurrentError;

/// RFC 9113 §6.8 processing certainty for a locally initiated request stream.
/// A stream above the peer's GOAWAY Last-Stream-ID is guaranteed not to have
/// been processed and can be retried on a new connection. Streams at or below
/// that boundary may already have application side effects.
pub const GoAwayRetryDisposition = enum {
    no_goaway,
    may_have_been_processed,
    safe_to_retry,
};

pub const ServeErrorStage = enum {
    accept,
    connection,
};

pub const ServeErrorPolicy = enum {
    continue_serving,
    stop,
};

pub const ServeErrorEvent = struct {
    stage: ServeErrorStage,
    err: anyerror,
};

pub const ServeErrorObserver = struct {
    context: *anyopaque,
    /// May be invoked concurrently by independent connection workers.
    observe: *const fn (context: *anyopaque, event: ServeErrorEvent) void,
};

pub const ServeUntilOptions = struct {
    /// Setting this event cancels pending accepts and active frame reads.
    shutdown: *std.Io.Event,
    accept_error_policy: ServeErrorPolicy = .continue_serving,
    connection_error_policy: ServeErrorPolicy = .continue_serving,
    /// Prevent a failed listener from becoming an unbounded retry loop.
    accept_error_backoff: std.Io.Duration = .fromMilliseconds(10),
    error_observer: ?ServeErrorObserver = null,
};

fn serveAcceptedConcurrent(
    comptime ServerType: type,
    server: *ServerType,
    io: std.Io,
    allocator: std.mem.Allocator,
    comptime HandlerContext: type,
    context: *HandlerContext,
    comptime handler: *const fn (
        *HandlerContext,
        OwnedRequest,
    ) Error!ResponseOptions,
    max_connections: usize,
) AsyncServeError!ConcurrentServeResult {
    var group: std.Io.Group = .init;
    const results = try allocator.alloc(?anyerror, max_connections);
    errdefer allocator.free(results);
    @memset(results, null);
    for (results) |*result| {
        var connection = try server.accept();
        errdefer connection.close();
        const task = ServeTask(HandlerContext){
            .connection = connection,
            .context = context,
            .handler = handler,
            .result = result,
        };
        group.async(io, ServeTask(HandlerContext).run, .{task});
    }
    try group.await(io);
    return .{ .allocator = allocator, .errors = results };
}

const ServeSupervisorState = struct {
    io: std.Io,
    options: ServeUntilOptions,
    stopping: std.atomic.Value(bool) = .init(false),
    failed: std.Io.Event = .unset,
    error_mutex: std.Io.Mutex = .init,
    first_error: ?anyerror = null,

    fn shouldStop(self: *@This()) bool {
        return self.stopping.load(.acquire) or self.options.shutdown.isSet();
    }

    fn report(self: *@This(), stage: ServeErrorStage, err: anyerror) void {
        if (self.options.error_observer) |observer| {
            observer.observe(observer.context, .{ .stage = stage, .err = err });
        }
        const policy = switch (stage) {
            .accept => self.options.accept_error_policy,
            .connection => self.options.connection_error_policy,
        };
        if (policy != .stop) return;
        self.error_mutex.lockUncancelable(self.io);
        if (self.first_error == null) self.first_error = err;
        self.error_mutex.unlock(self.io);
        self.stopping.store(true, .release);
        self.failed.set(self.io);
    }

    fn firstError(self: *@This()) ?anyerror {
        self.error_mutex.lockUncancelable(self.io);
        defer self.error_mutex.unlock(self.io);
        return self.first_error;
    }
};

fn serveAcceptedUntil(
    comptime ServerType: type,
    server: *ServerType,
    io: std.Io,
    comptime HandlerContext: type,
    context: *HandlerContext,
    comptime handler: *const fn (
        *HandlerContext,
        OwnedRequest,
    ) Error!ResponseOptions,
    max_connections: usize,
    max_requests_per_connection: usize,
    options: ServeUntilOptions,
) anyerror!void {
    if (max_connections == 0 or max_requests_per_connection == 0 or
        options.accept_error_backoff.nanoseconds < 0)
    {
        return error.InvalidServeOptions;
    }
    var group: std.Io.Group = .init;
    var supervisor = ServeSupervisorState{ .io = io, .options = options };
    var group_finished = false;
    defer if (!group_finished) {
        supervisor.stopping.store(true, .release);
        group.cancel(io);
    };
    for (0..max_connections) |_| {
        try group.concurrent(
            io,
            ServeUntilTask(ServerType, HandlerContext, handler).run,
            .{ServeUntilTask(ServerType, HandlerContext, handler){
                .supervisor = &supervisor,
                .server = server,
                .context = context,
                .max_requests_per_connection = max_requests_per_connection,
            }},
        );
    }

    const Wake = union(enum) {
        shutdown: std.Io.Cancelable!void,
        failure: std.Io.Cancelable!void,
    };
    var wake_buffer: [2]Wake = undefined;
    var select: std.Io.Select(Wake) = .init(io, &wake_buffer);
    defer select.cancelDiscard();
    try select.concurrent(.shutdown, waitForServeEvent, .{ options.shutdown, io });
    try select.concurrent(.failure, waitForServeEvent, .{ &supervisor.failed, io });
    switch (try select.await()) {
        .shutdown => |result| try result,
        .failure => |result| try result,
    }
    supervisor.stopping.store(true, .release);
    group.cancel(io);
    group_finished = true;
    select.cancelDiscard();
    if (supervisor.firstError()) |err| return err;
}

fn ServeUntilTask(
    comptime ServerType: type,
    comptime HandlerContext: type,
    comptime handler: *const fn (
        *HandlerContext,
        OwnedRequest,
    ) Error!ResponseOptions,
) type {
    return struct {
        supervisor: *ServeSupervisorState,
        server: *ServerType,
        context: *HandlerContext,
        max_requests_per_connection: usize,

        fn run(task: @This()) std.Io.Cancelable!void {
            while (!task.supervisor.shouldStop()) {
                var connection = task.server.accept() catch |err| {
                    if (err == error.Canceled or
                        task.supervisor.shouldStop())
                    {
                        return error.Canceled;
                    }
                    task.supervisor.report(.accept, err);
                    if (task.supervisor.shouldStop()) return;
                    const backoff =
                        task.supervisor.options.accept_error_backoff;
                    if (backoff.nanoseconds > 0) {
                        std.Io.sleep(
                            task.supervisor.io,
                            backoff,
                            .awake,
                        ) catch |sleep_err| switch (sleep_err) {
                            error.Canceled => return error.Canceled,
                        };
                    }
                    continue;
                };
                defer connection.close();
                _ = connection.serve(
                    HandlerContext,
                    task.context,
                    handler,
                    task.max_requests_per_connection,
                ) catch |err| {
                    if (err == error.Canceled and
                        task.supervisor.shouldStop()) return;
                    task.supervisor.report(.connection, err);
                };
            }
        }
    };
}

fn waitForServeEvent(
    event: *std.Io.Event,
    io: std.Io,
) std.Io.Cancelable!void {
    try event.wait(io);
}

fn ServeTask(comptime HandlerContext: type) type {
    return struct {
        connection: Connection,
        context: *HandlerContext,
        handler: *const fn (*HandlerContext, OwnedRequest) Error!ResponseOptions,
        result: *?anyerror,

        fn run(task: @This()) std.Io.Cancelable!void {
            var connection = task.connection;
            defer connection.close();

            connection.serve_read_connection_error = null;
            connection.serve_read_stream_error = null;
            var request = connection.readRequest() catch |err| {
                connection.sendServeReadError(err);
                task.result.* = err;
                return;
            };
            defer request.deinit(connection.allocator);

            var response = task.handler(task.context, request) catch |err| {
                task.result.* = err;
                return;
            };
            const invalid_final = normalizeHandlerResponse(
                &response,
                request.method,
                request.protocol != null,
            );
            connection.writeResponse(request.stream_id, response) catch |err| {
                task.result.* = err;
                return;
            };
            task.result.* = if (invalid_final) error.InvalidStatus else null;
        }
    };
}

pub const Client = struct {
    /// Adopt an already connected cleartext stream and perform the HTTP/2
    /// prior-knowledge preface/SETTINGS bootstrap. Ownership transfers at
    /// entry; the authority is copied for later requests.
    pub fn adoptPriorKnowledgeStream(
        allocator: std.mem.Allocator,
        io: std.Io,
        stream: net.Stream,
        authority: []const u8,
        limits: Limits,
    ) Error!Connection {
        if (authority.len == 0) {
            stream.close(io);
            return error.InvalidHeader;
        }
        var connection = try connectStream(allocator, io, stream, limits);
        errdefer connection.close();
        connection.default_authority = try allocator.dupe(u8, authority);
        connection.default_scheme = "http";
        return connection;
    }

    pub fn adoptPriorKnowledgeStreamWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        stream: net.Stream,
        authority: []const u8,
        limits: Limits,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        if (authority.len == 0) {
            stream.close(io);
            return error.InvalidHeader;
        }
        var connection = try connectStreamBefore(
            allocator,
            io,
            stream,
            limits,
            deadline,
        );
        errdefer connection.close();
        connection.default_authority = try allocator.dupe(u8, authority);
        connection.default_scheme = "http";
        return connection;
    }

    /// Adopt a certificate-verified TLS connection already negotiated as
    /// `h2`, then complete the HTTP/2 bootstrap. Ownership transfers at entry.
    pub fn adoptNegotiatedTls(
        allocator: std.mem.Allocator,
        io: std.Io,
        tls_connection: *tls_stream.ClientConnection,
        authority: []const u8,
        limits: Limits,
    ) Error!Connection {
        return adoptNegotiatedTlsMaybeBefore(
            allocator,
            io,
            tls_connection,
            authority,
            limits,
            null,
        );
    }

    pub fn adoptNegotiatedTlsWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        tls_connection: *tls_stream.ClientConnection,
        authority: []const u8,
        limits: Limits,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        _ = try deadline_policy.usableAwake(io, deadline);
        return adoptNegotiatedTlsMaybeBefore(
            allocator,
            io,
            tls_connection,
            authority,
            limits,
            deadline,
        );
    }

    fn adoptNegotiatedTlsMaybeBefore(
        allocator: std.mem.Allocator,
        io: std.Io,
        tls_connection: *tls_stream.ClientConnection,
        authority: []const u8,
        limits: Limits,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!Connection {
        var tls_owned = true;
        errdefer if (tls_owned) tls_connection.deinit();
        try validateLocalLimits(limits);
        if (authority.len == 0) return error.InvalidHeader;
        const selected = tls_connection.negotiatedAlpn() orelse
            return error.InvalidAlpn;
        if (!std.mem.eql(u8, selected, "h2")) return error.InvalidAlpn;
        if (limits.tcp_nodelay) {
            try socket_options.setTcpNoDelay(tls_connection.stream);
        }
        const owned_authority = try allocator.dupe(u8, authority);
        errdefer allocator.free(owned_authority);
        tls_owned = false;
        var connection = if (deadline) |absolute|
            try connectTransportBefore(
                allocator,
                io,
                tls_connection.stream,
                .{ .tls_client = tls_connection },
                limits,
                absolute,
            )
        else
            try connectTransport(
                allocator,
                io,
                tls_connection.stream,
                .{ .tls_client = tls_connection },
                limits,
            );
        connection.default_authority = owned_authority;
        connection.default_scheme = "https";
        return connection;
    }

    pub fn connect(allocator: std.mem.Allocator, io: std.Io, address: net.IpAddress, limits: Limits) Error!Connection {
        try validateLocalLimits(limits);
        const stream = try tcp_connect.ip(io, address, limits.connect_timeout);
        var connection = try connectStream(allocator, io, stream, limits);
        connection.default_scheme = "http";
        return connection;
    }

    /// Establish TCP and complete the HTTP/2 SETTINGS exchange under one
    /// caller-owned deadline while retaining stricter configured phase limits.
    pub fn connectWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        address: net.IpAddress,
        limits: Limits,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        try validateLocalLimits(limits);
        const stream = try tcp_connect.ipWithDeadline(
            io,
            address,
            try deadline_policy.capTimeout(
                io,
                deadline,
                limits.connect_timeout,
            ),
        );
        var connection = try connectStreamBefore(
            allocator,
            io,
            stream,
            limits,
            deadline,
        );
        connection.default_scheme = "http";
        return connection;
    }

    pub fn connectWithTimeout(
        allocator: std.mem.Allocator,
        io: std.Io,
        address: net.IpAddress,
        limits: Limits,
        timeout: std.Io.Duration,
    ) Error!Connection {
        if (timeout.nanoseconds <= 0) return error.Timeout;
        return connectWithDeadline(
            allocator,
            io,
            address,
            limits,
            .fromNow(io, .{ .raw = timeout, .clock = .awake }),
        );
    }

    /// Connect with HTTP/2 prior knowledge over a Unix-domain stream.
    /// `authority` is copied for subsequent requests that omit it; the local
    /// transport still uses the `http` scheme and skips TCP-only NODELAY.
    pub fn connectUnix(
        allocator: std.mem.Allocator,
        io: std.Io,
        address: net.UnixAddress,
        authority: []const u8,
        limits: Limits,
    ) Error!Connection {
        try validateLocalLimits(limits);
        if (authority.len == 0) return error.InvalidHeader;
        const owned_authority = try allocator.dupe(u8, authority);
        errdefer allocator.free(owned_authority);
        const stream = try tcp_connect.unix(io, address, limits.connect_timeout);
        var connection = try connectStreamWithoutTcpOptions(
            allocator,
            io,
            stream,
            limits,
        );
        connection.default_authority = owned_authority;
        connection.default_scheme = "http";
        return connection;
    }

    pub fn connectUnixWithDeadline(
        allocator: std.mem.Allocator,
        io: std.Io,
        address: net.UnixAddress,
        authority: []const u8,
        limits: Limits,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        try validateLocalLimits(limits);
        if (authority.len == 0) return error.InvalidHeader;
        const owned_authority = try allocator.dupe(u8, authority);
        errdefer allocator.free(owned_authority);
        const stream = try tcp_connect.unixWithDeadline(
            io,
            address,
