    fn connectTransport(
        allocator: std.mem.Allocator,
        io: std.Io,
        stream: net.Stream,
        transport: RuntimeTransport,
        limits: Limits,
    ) Error!Connection {
        return connectTransportMaybeBefore(
            allocator,
            io,
            stream,
            transport,
            limits,
            null,
        );
    }

    fn connectTransportBefore(
        allocator: std.mem.Allocator,
        io: std.Io,
        stream: net.Stream,
        transport: RuntimeTransport,
        limits: Limits,
        deadline: std.Io.Clock.Timestamp,
    ) Error!Connection {
        return connectTransportMaybeBefore(
            allocator,
            io,
            stream,
            transport,
            limits,
            deadline,
        );
    }

    fn connectTransportMaybeBefore(
        allocator: std.mem.Allocator,
        io: std.Io,
        stream: net.Stream,
        transport: RuntimeTransport,
        limits: Limits,
        outer_deadline: ?std.Io.Clock.Timestamp,
    ) Error!Connection {
        var transport_owned = true;
        errdefer if (transport_owned) transport.close();
        const deadline = if (outer_deadline) |absolute|
            try connectionHandshakeDeadlineBefore(
                transport,
                absolute,
                limits.handshake_timeout,
            )
        else
            try connectionHandshakeDeadline(
                transport,
                limits.handshake_timeout,
            );
        try transport.writeAll(http2.connection_preface);
        try writeInitialSettingsTransport(allocator, transport, limits, .client);
        try writeInitialConnectionWindowTransport(allocator, transport, limits);

        var connection = Connection{
            .io = io,
            .allocator = allocator,
            .stream = stream,
            .transport = transport,
            .role = .client,
            .limits = limits,
            .last_peer_frame_at = std.Io.Clock.awake.now(io),
            .awaiting_settings_ack = true,
        };
        transport_owned = false;
        connection.applyLocalLimits();
        errdefer connection.close();
        try finishClientSettingsHandshake(&connection, deadline);
        return connection;
    }

    fn finishClientSettingsHandshake(
        connection: *Connection,
        deadline: ?std.Io.Clock.Timestamp,
    ) Error!void {
        var saw_server_settings = false;
        var saw_settings_ack = false;
        while (!saw_server_settings or !saw_settings_ack) {
            var frame = try readHandshakeFrameTransportWithDeadline(
                connection.allocator,
                connection.transportForIo(),
                connection.limits,
                deadline,
            );
            defer frame.deinit(connection.allocator);
            if (frame.frame.header.frame_type != .settings) {
                if (try connection.handleConnectionOrGoAwayFrame(frame.frame)) continue;
                return error.UnexpectedFrame;
            }
            if ((frame.frame.header.flags & flag_ack) != 0) {
                saw_settings_ack = true;
                try connection.applySettingsAck();
            } else {
                saw_server_settings = true;
                try connection.applyPeerSettingsPayload(
                    frame.frame.payload,
                    deadline,
                );
                try writeFrameTransport(
                    connection.allocator,
                    connection.transportForIo(),
                    .settings,
                    flag_ack,
                    0,
                    &.{},
                );
            }
        }
    }

