    ) Error!void {
        if (!try connection.handleConnectionFrame(frame)) {
            return error.UnexpectedFrame;
        }
    }

    pub fn reserveNextClientStreamId(
        connection: *Connection,
    ) Error!u31 {
        return connection.reserveNextClientStreamId();
